#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long extend(int n, int length, vector<char>& used) {
    long long total = 1;
    if (length == n) return total;
    for (int d = 0; d < 10; d++) {
        if (!used[d]) {
            used[d] = 1;
            total += extend(n, length + 1, used);
            used[d] = 0;
        }
    }
    return total;
}

int main() {
    long long n;
    cin >> n;

    vector<char> used(10, 0);
    long long total = 1;
    for (int first = 1; first <= 9; first++) {
        used[first] = 1;
        total += extend((int)n, 1, used);
        used[first] = 0;
    }
    cout << total << "\n";

    return 0;
}

